(function(r,f){if(typeof module==='object')module.exports=f();else r.DefenderEngine=f()})(typeof window==='object'?window:this,()=>{const learning=()=>typeof ArcadeLearning!=='undefined'?ArcadeLearning:(typeof window!=='undefined'?window.ArcadeLearning:null);function recordPractice(owner,correct,timeout=false){const api=learning(),q=owner.question;if(!api?.active||!q||q.completed||owner.practiceAnsweredQuestion===q)return false;owner.practiceAnsweredQuestion=q;api.record(q,correct,undefined,{timeout});return true;}
class Game{constructor(o={}){this.random=o.random||Math.random;this.timed=!!o.timed;this.op=o.operation||'add';this.range=o.range||10;this.shields=3;this.correct=0;this.kills=0;this.coins=0;this.charge=0;this.wave=1;this.level=1;this.running=true;this.cooldown=0;this.questionElapsed=0;this.events=[];this.shots=[];this.id=0;this.question=this.makeQuestion();this.spawn()}
makeQuestion(){if(learning()?.active)return learning().next();let a=1+Math.floor(this.random()*this.range),b=1+Math.floor(this.random()*this.range),op=this.op==='mix'?['add','sub','mul','div'][Math.floor(this.random()*4)]:this.op;const answer=op==='add'?a+b:op==='mul'?a*b:b;const text=op==='add'?a+' + '+b:op==='mul'?a+' × '+b:op==='sub'?(a+b)+' − '+a:(a*b)+' ÷ '+a;const set=new Set([answer]);for(const x of [answer+1,answer-1,answer+a,answer+b,answer+2])if(x>=0&&set.size<4)set.add(x);const choices=[...set];while(choices.length<4)choices.push(answer+choices.length+2);for(let i=3;i>0;i--){const j=Math.floor(this.random()*(i+1));[choices[i],choices[j]]=[choices[j],choices[i]]}return{text,answer,choices}}
spawn(){this.aliens=Array.from({length:12},(_,i)=>({id:++this.id,x:.17+(i%4)*.22,y:.13+Math.floor(i/4)*.1,row:Math.floor(i/4),boss:false}));if(this.wave%3===0)this.aliens.push({id:++this.id,x:.5,y:.075,row:-1,boss:true,hp:3});this.events.push({type:'wave',wave:this.wave})}
answer(value,timeout=false){if(this.question?.completed||!this.running||this.cooldown>0)return false;timeout=timeout||this.questionElapsed>=3-1e-9;if(timeout)value=null;recordPractice(this,value===this.question.answer,timeout);this.cooldown=.55;this.pending=true;if(value!==this.question.answer){this.charge=0;this.events.push({type:'wrong',text:this.question.text,answer:this.question.answer,timeout});return false}this.correct++;this.level=1+Math.floor(this.correct/5);this.charge++;const beam=this.charge===4;if(beam)this.charge=0;const targets=this.aliens.filter(a=>!a.targeted).sort((a,b)=>b.y-a.y).slice(0,beam?4:1);for(const a of targets){a.targeted=true;this.shots.push({id:a.id,left:.28,beam});this.events.push({type:'shot',alien:{...a},beam})}this.events.push({type:'fire',beam});return true}
update(dt){if(!this.running||!Number.isFinite(dt)||dt<0)return;this.cooldown=Math.max(0,this.cooldown-dt);if(this.pending&&this.cooldown===0){this.pending=false;this.question=this.makeQuestion();this.questionElapsed=0}else if(!this.pending&&this.cooldown===0){this.questionElapsed+=dt;if(this.questionElapsed>=3-1e-9)this.answer(null,true)}for(const shot of this.shots){shot.left-=dt;if(shot.left>0)continue;const a=this.aliens.find(a=>a.id===shot.id);if(!a)continue;a.targeted=false;if(a.boss&&!shot.beam&&--a.hp>0){this.events.push({type:'damage',alien:{...a}});continue}this.aliens=this.aliens.filter(v=>v.id!==a.id);this.kills++;const award=a.boss?75:15;this.coins+=award;this.events.push({type:'destroy',alien:{...a},coins:award,beam:shot.beam})}this.shots=this.shots.filter(s=>s.left>0);if(!this.aliens.length){this.wave++;this.spawn()}const speed=.022+Math.min(.075,(this.level-1)*.004)+(this.wave-1)*.001;for(const a of this.aliens)a.y+=speed*dt;if(this.aliens.some(a=>a.y>=.87)){this.shields--;this.charge=0;for(const a of this.aliens)a.y=Math.max(.05,a.y-.27);this.events.push({type:'shield',remaining:this.shields});if(this.shields===0){if(this.timed){this.shields=3;this.events.push({type:'recharge'})}else{this.running=false;this.events.push({type:'over'})}}}}
get questionRemaining(){return Math.max(0,3-this.questionElapsed)}drain(){const e=this.events;this.events=[];return e}}return{Game}});
